    public ReturnLoanService(LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                             LoadBookPort loadBookPort, SaveBookPort saveBookPort) {
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
    }

    @Override
    public Loan returnLoan(UUID loanId, LocalDate returnedAt) {
        // 대출 행을 잠가 같은 대출의 동시 반납 요청이 둘 다 성공하지 못하게 한다.
        Loan loan = loadLoanPort.loadLoanForUpdate(loanId)
                .orElseThrow(() -> new LoanNotFoundException(loanId));
        loan.returnOn(returnedAt != null ? returnedAt : LocalDate.now());
        // 도서 행을 잠가 반납과 예약 요청이 서로의 상태 검사를 통과하지 못하게 한다.
        Book book = loadBookPort.loadBookForUpdate(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        book.setStatus(BookStatus.AVAILABLE);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
    }
