package com.example.lending.domain;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Embeddable;
import jakarta.persistence.JoinColumn;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

// 외부 신용조회 결과. 분쟁 대응을 위해 대출과 함께 보관한다.
@Embeddable
public record CreditCheck(
        @Column(name = "credit_approved") boolean approved,
        @Column(name = "credit_score") int score,
        @ElementCollection
        @CollectionTable(name = "loan_credit_reason_code", joinColumns = @JoinColumn(name = "loan_id"))
        @Column(name = "reason_code") List<String> reasonCodes,
        @Column(name = "credit_checked_at") Instant checkedAt,
        @Column(name = "credit_provider_name") String providerName,
        @Column(name = "credit_provider_version") String providerVersion) {

    public CreditCheck {
        Objects.requireNonNull(checkedAt, "checkedAt");
        reasonCodes = reasonCodes == null ? List.of() : List.copyOf(reasonCodes);
    }
}

